import { Badge, Button, Input, Surface, Table, Tabs, Text } from "@cloudflare/kumo";
import { Plus, ArrowsClockwise } from "@phosphor-icons/react";
import { useState } from "react";

const datasets = [
  {
    name: "github_events",
    source: "GitHub API",
    type: "Table",
    records: "1.2M",
    updated: "2026-04-05",
    status: "active",
  },
  {
    name: "github_repos",
    source: "GitHub API",
    type: "Table",
    records: "340",
    updated: "2026-04-04",
    status: "active",
