  });

  it("検索結果がない場合、nullを返す", async () => {
    (semanticSearch as Mock).mockResolvedValueOnce([]);
    const env = createMockEnv();

    const result = await retrieveRelevantContext(env, "存在しないトピック");

    expect(result).toBeNull();
  });
});

